		if swiftLeadingOperatorContinuationLinePattern.MatchString(text) {
			if strings.Contains(text, "{") {
				balance := strings.Count(text, "(") - strings.Count(text, ")")
				balance += strings.Count(text, "{") - strings.Count(text, "}")
				lines[i] = maskLineText(text) + newline
