"""Measure Swift parse failures and Swift symbols for one entire-graph binary.

usage: python3 -I measure.py <binary> <out.json>
"""

import json
import subprocess
import sys

S = "/private/tmp/claude-502/-Users-rod-build-entire-graph/7bfdd797-ea5f-4338-80e4-17ab056773fd/scratchpad"
REPOS = {
    "hummingbird": f"{S}/secondary/hummingbird",
    "onionbrowser": f"{S}/secondary/onionbrowser",
    "firefox-ios": f"{S}/secondary/firefox-ios",
    "porter": "/Users/rod/build/porter",
}


def measure(binary, path):
    proc = subprocess.Popen(
        [binary, "snapshot", "--repo", path, "--worktree", "--profile", "full", "--format", "ndjson"],
        stdout=subprocess.PIPE,
        stderr=subprocess.DEVNULL,
        text=True,
    )
    symbols = 0
    failures = {}
    for line in proc.stdout:
        rec = json.loads(line)
        kind = rec.get("record_type")
        if kind == "symbol" and rec.get("language") == "Swift":
            symbols += 1
        elif kind == "summary":
            for p in rec.get("partial_failures", []):
                if p["file_path"].endswith(".swift"):
                    failures[p["file_path"]] = p.get("detail", "")
    proc.wait()
    return {"swift_symbols": symbols, "swift_failures": len(failures), "failed_files": failures}


def main():
    binary, out = sys.argv[1], sys.argv[2]
    result = {name: measure(binary, path) for name, path in REPOS.items()}
    with open(out, "w") as f:
        json.dump(result, f, indent=1)
    for name, r in result.items():
        print(f"{name:14} failures={r['swift_failures']:5} symbols={r['swift_symbols']}")


if __name__ == "__main__":
    main()

