"""Compare symbols and parse failures for selected files between two binaries.

usage: python3 -I symdiff.py <probe-repo> <binA> <binB> <src-root> <file>...
Copies each file from src-root into probe-repo (an existing git repo), then
snapshots the probe with both binaries.
"""

import json
import os
import shutil
import subprocess
import sys


def run(binary, probe):
    out = subprocess.run(
        [binary, "snapshot", "--repo", probe, "--worktree", "--profile", "full", "--format", "ndjson"],
        capture_output=True,
        text=True,
    ).stdout
    syms, fails = {}, {}
    for line in out.splitlines():
        r = json.loads(line)
        if r.get("record_type") == "symbol":
            syms.setdefault(r["file_path"], set()).add((r["kind"], r["qualified_name"], r["start_line"]))
        elif r.get("record_type") == "summary":
            for p in r["partial_failures"]:
                fails[p["file_path"]] = p.get("detail", "")[:220]
    return syms, fails


def main():
    probe, bin_a, bin_b, root, files = sys.argv[1], sys.argv[2], sys.argv[3], sys.argv[4], sys.argv[5:]
    for f in files:
        dst = os.path.join(probe, f)
        os.makedirs(os.path.dirname(dst), exist_ok=True)
        shutil.copy(os.path.join(root, f), dst)
    a, fa = run(bin_a, probe)
    b, fb = run(bin_b, probe)
    for f in files:
        print("==", f)
        print("  fail A:", fa.get(f, "-"))
        print("  fail B:", fb.get(f, "-"))
        for s in sorted(a.get(f, set()) - b.get(f, set()))[:8]:
            print("  only A:", s)
        for s in sorted(b.get(f, set()) - a.get(f, set()))[:5]:
            print("  only B:", s)


if __name__ == "__main__":
    main()

