func maskSwiftEmptyAttributeCalls(text string) string {
	return swiftEmptyAttributeCallPattern.ReplaceAllStringFunc(text, func(match string) string {
		return strings.TrimSuffix(match, "()") + strings.Repeat(" ", len("()"))
