	if err := saveManifest(path, grammars); err != nil {
		t.Fatal(err)
	}
	got, _ := os.ReadFile(path)
	if string(got) != original {
		t.Fatalf("round trip changed manifest:\n%s", got)
	}
}

func TestUpsertKeepsManifestSorted(t *testing.T) {
	grammars := []Grammar{{Language: "dart"}, {Language: "zig"}}
	grammars = upsert(grammars, Grammar{Language: "swift", Revision: "a"})
	grammars = upsert(grammars, Grammar{Language: "swift", Revision: "b"})
	var names []string
	for _, g := range grammars {
		names = append(names, g.Language)
	}
	if !reflect.DeepEqual(names, []string{"dart", "swift", "zig"}) || grammars[1].Revision != "b" {
		t.Fatalf("upsert = %+v", grammars)
	}
}

package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"
)

const (
	minABI = 13
	maxABI = 14
)

// Grammar is one vendored grammar's origin, as recorded in grammars.json.
type Grammar struct {
	Language  string   `json:"language"`
	URL       string   `json:"url"`
	Reference string   `json:"reference"`
	Revision  string   `json:"revision"`
	Path      string   `json:"path,omitempty"`
	Files     []string `json:"files"`
	ABI       int      `json:"abi"`
	Note      string   `json:"note,omitempty"`
}

var languageVersionPattern = regexp.MustCompile(`(?m)^#define LANGUAGE_VERSION (\d+)\s*$`)

func languageABI(parserC []byte) (int, error) {
	m := languageVersionPattern.FindSubmatch(parserC)
	if m == nil {
		return 0, fmt.Errorf("parser.c has no #define LANGUAGE_VERSION")
	}
	return strconv.Atoi(string(m[1]))
}

// vendor copies a generated grammar from repoRoot/subdir into destDir:
// src/parser.c, src/scanner.c when present, src/tree_sitter/*.h and the
// license file (from the grammar directory, else the repository root). Files
// of those kinds already in destDir that the new grammar lacks are removed;
// everything else there, such as binding.go, is left alone. Nothing in destDir
// changes unless the grammar has a parser.c the go-tree-sitter runtime can load.
func vendor(repoRoot, subdir, destDir string) ([]string, int, error) {
	grammarRoot := filepath.Join(repoRoot, subdir)
	parserC, err := os.ReadFile(filepath.Join(grammarRoot, "src", "parser.c"))
	if err != nil {
		return nil, 0, fmt.Errorf("%s has no generated src/parser.c (is this a ref with generated files?): %w", filepath.Join(subdir, "src"), err)
	}
	abi, err := languageABI(parserC)
	if err != nil {
		return nil, 0, err
	}
	if abi < minABI || abi > maxABI {
		return nil, 0, fmt.Errorf("grammar is ABI %d, but the go-tree-sitter runtime accepts ABI %d-%d; regenerate it with `tree-sitter generate --abi 14` and vendor the result", abi, minABI, maxABI)
	}

	sources := map[string]string{"parser.c": filepath.Join(grammarRoot, "src", "parser.c")}
	if scanner := filepath.Join(grammarRoot, "src", "scanner.c"); fileExists(scanner) {
		sources["scanner.c"] = scanner
	}
	headers, err := filepath.Glob(filepath.Join(grammarRoot, "src", "tree_sitter", "*.h"))
	if err != nil {
		return nil, 0, err
	}
	for _, h := range headers {
		sources["tree_sitter/"+filepath.Base(h)] = h
	}
	license := findLicense(grammarRoot)
	if license == "" {
		license = findLicense(repoRoot)
	}
	if license == "" {
		return nil, 0, fmt.Errorf("no LICENSE or COPYING file in %s or the repository root", grammarRoot)
	}
	sources[filepath.Base(license)] = license

	stale, err := vendoredFiles(destDir)
	if err != nil {
		return nil, 0, err
	}
	for _, rel := range stale {
		if _, keep := sources[rel]; !keep {
			if err := os.Remove(filepath.Join(destDir, filepath.FromSlash(rel))); err != nil {
				return nil, 0, err
			}
		}
	}
	files := make([]string, 0, len(sources))
	for rel, src := range sources {
		data, err := os.ReadFile(src)
		if err != nil {
			return nil, 0, err
		}
		dst := filepath.Join(destDir, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return nil, 0, err
		}
		if err := os.WriteFile(dst, data, 0o644); err != nil {
			return nil, 0, err
		}
		files = append(files, rel)
	}
	sort.Strings(files)
	return files, abi, nil
}

func fileExists(path string) bool {
	info, err := os.Stat(path)
	return err == nil && !info.IsDir()
}

func findLicense(dir string) string {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return ""
	}
	for _, e := range entries {
		name := strings.ToUpper(e.Name())
		if !e.IsDir() && (strings.HasPrefix(name, "LICENSE") || strings.HasPrefix(name, "COPYING")) {
			return filepath.Join(dir, e.Name())
		}
	}
	return ""
}

// vendoredFiles lists the files in destDir that vendor manages.
func vendoredFiles(destDir string) ([]string, error) {
	var out []string
	entries, err := os.ReadDir(destDir)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	for _, e := range entries {
		name := e.Name()
		upper := strings.ToUpper(name)
		switch {
		case e.IsDir() && name == "tree_sitter":
			headers, err := filepath.Glob(filepath.Join(destDir, "tree_sitter", "*.h"))
			if err != nil {
				return nil, err
			}
			for _, h := range headers {
				out = append(out, "tree_sitter/"+filepath.Base(h))
			}
		case name == "parser.c" || name == "scanner.c",
			strings.HasPrefix(upper, "LICENSE"), strings.HasPrefix(upper, "COPYING"):
			out = append(out, name)
		}
	}
	return out, nil
}

func loadManifest(path string) ([]Grammar, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, err
	}
	var grammars []Grammar
	if err := json.Unmarshal(data, &grammars); err != nil {
		return nil, fmt.Errorf("%s: %w", path, err)
	}
	return grammars, nil
}

func saveManifest(path string, grammars []Grammar) error {
	var buf bytes.Buffer
	enc := json.NewEncoder(&buf)
	enc.SetEscapeHTML(false)
	enc.SetIndent("", "  ")
	if err := enc.Encode(grammars); err != nil {
		return err
	}
	return os.WriteFile(path, buf.Bytes(), 0o644)
}

// upsert replaces the entry for g.Language, or inserts it, keeping the
// manifest sorted by language.
func upsert(grammars []Grammar, g Grammar) []Grammar {
	i := sort.Search(len(grammars), func(i int) bool { return grammars[i].Language >= g.Language })
	if i < len(grammars) && grammars[i].Language == g.Language {
		grammars[i] = g
		return grammars
	}
	grammars = append(grammars, Grammar{})
	copy(grammars[i+1:], grammars[i:])
	grammars[i] = g
	return grammars
}

// Command grammar-refresh vendors a tree-sitter grammar into
// internal/sem/grammars/<lang> from its upstream git repository and records
// where it came from in internal/sem/grammars/grammars.json. It is a
// maintainer tool: it needs the network, and its output is committed, so
// building entire-graph never downloads anything.
//
// Usage:
//
//	go run ./cmd/grammar-refresh -lang swift -ref 0.7.4-with-generated-files
//	go run ./cmd/grammar-refresh -lang fsharp -ref <commit> -path fsharp
//	go run ./cmd/grammar-refresh -lang newlang -ref v1.0.0 -url https://github.com/o/tree-sitter-newlang
//
// The ref must contain generated sources (src/parser.c) built for ABI 13-14,
// the range the go-tree-sitter runtime loads. binding.go is never touched, so
// a new language still needs one. A grammar that changes parse results needs
// an IdentityRevision bump (internal/sem/provider.go) in the same commit.
package main

import (
	"flag"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
)

func main() {
	var (
		lang         = flag.String("lang", "", "grammar directory name under -dir (required)")
		ref          = flag.String("ref", "", "tag, branch or full commit to vendor (required)")
		url          = flag.String("url", "", "git URL; defaults to the manifest entry")
		subdir       = flag.String("path", "", "grammar subdirectory within the repository; defaults to the manifest entry")
		manifestPath = flag.String("manifest", "internal/sem/grammars/grammars.json", "path to the grammar manifest")
		grammarsDir  = flag.String("dir", "internal/sem/grammars", "directory holding vendored grammars")
	)
	flag.Parse()
	if *lang == "" || *ref == "" {
		flag.Usage()
		os.Exit(2)
	}
	if err := refresh(*lang, *ref, *url, *subdir, *manifestPath, *grammarsDir); err != nil {
		fmt.Fprintln(os.Stderr, "grammar-refresh:", err)
		os.Exit(1)
	}
}

func refresh(lang, ref, url, subdir, manifestPath, grammarsDir string) error {
	grammars, err := loadManifest(manifestPath)
	if err != nil {
		return err
	}
	var existing Grammar
	for _, g := range grammars {
		if g.Language == lang {
			existing = g
		}
	}
	if url == "" {
		url = existing.URL
	}
	if url == "" {
		return fmt.Errorf("%s is not in %s; pass -url", lang, manifestPath)
	}
	if subdir == "" {
		subdir = existing.Path
	}

	tmp, err := os.MkdirTemp("", "grammar-refresh-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(tmp)
	if err := git(tmp, "init", "-q"); err != nil {
		return err
	}
	if err := git(tmp, "fetch", "-q", "--depth", "1", url, ref); err != nil {
		return fmt.Errorf("fetch %s %s: %w", url, ref, err)
	}
	if err := git(tmp, "checkout", "-q", "FETCH_HEAD"); err != nil {
		return err
	}
	revision, err := gitOutput(tmp, "rev-parse", "HEAD")
	if err != nil {
		return err
	}

	files, abi, err := vendor(tmp, subdir, filepath.Join(grammarsDir, lang))
	if err != nil {
		return err
	}
	note := ""
	if existing.Revision == revision {
		note = existing.Note
	}
	grammars = upsert(grammars, Grammar{
		Language:  lang,
		URL:       url,
		Reference: ref,
		Revision:  revision,
		Path:      subdir,
		Files:     files,
		ABI:       abi,
		Note:      note,
	})
	if err := saveManifest(manifestPath, grammars); err != nil {
		return err
	}
	fmt.Printf("vendored %s %s (%s, ABI %d) into %s\n", lang, ref, revision[:7], abi, filepath.Join(grammarsDir, lang))
	fmt.Println("next: bump IdentityRevision in internal/sem/provider.go if parse results change, and run scripts/gen-notices.sh")
	return nil
}

func git(dir string, args ...string) error {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Stderr = os.Stderr
	return cmd.Run()
}

func gitOutput(dir string, args ...string) (string, error) {
	cmd := exec.Command("git", args...)
	cmd.Dir = dir
	cmd.Stderr = os.Stderr
	out, err := cmd.Output()
	return strings.TrimSpace(string(out)), err
}

